# NEXA Society Engine Test Script

Set-Location $PSScriptRoot

python -c "from datetime import datetime; from society_engine import SocietyEngine; society = SocietyEngine(); factions = ['government', 'union', 'corporation', 'criminal_faction', 'police']; occupations = ['Worker', 'Shopkeeper', 'Journalist', 'Police Officer', 'Teacher', 'Driver', 'Nurse', 'Unemployed']; [society.create_citizen(name=f'Citizen {i:03}', age=18 + (i % 55), occupation=occupations[i % len(occupations)], faction_id=factions[i % len(factions)], employed=(i % 4 != 0), has_home=(i % 10 != 0)) for i in range(1, 101)]; citizens = society.get_citizens(); [society.relationship_system.add_relationship(citizens[i].id, citizens[(i + 1) % len(citizens)].id, 'friend', trust=55, affection=50, respect=45) for i in range(len(citizens))]; society.tick(day=1, simulation_time=datetime.now(), crime_pressure=35, political_pressure=45); state = society.get_state(); print('NEXA Society Test Complete'); print(f'Citizens created: {state['citizen_count']}'); print('Faction relationships:'); [print(f'  {key}: {value}') for key, value in state['faction_relationships'].items()]; print('Citizen activities:'); [print(f'  {key}: {value}') for key, value in state['activities'].items()]; print('Sample citizens:'); [print(f'  {citizen.name} | {citizen.occupation} | {citizen.current_activity}') for citizen in society.get_citizens()[:5]]"
